  'intake.plan_mode.opt.week_by_week': ['Week by week (no longer used: use the Week view of a 12-week plan)', 'Semana a semana (ya no se usa: usa la vista Semana de un plan de 12 semanas)'],
  'intake.plan_mode.opt.year': ['A full year (stay in shape; you can change it)', 'Un año completo (para estar en forma; lo puedes cambiar)'],
