  'prehab.code.SHOULDER_THROWER': ['throwing shoulders', 'hombros de lanzador'],
  'prehab.label.ACHILLES_CALF': ['Joint care for the Achilles and calves', 'Cuidado del Aquiles y las pantorrillas'],
  'prehab.label.OVERHEAD_HEALTH': ['Healthy shoulders: a light overhead press through your full range, once a week. Your incline press builds the strength. This keeps your reach', 'Hombros sanos: un press ligero sobre la cabeza en todo tu rango, una vez a la semana. Tu press inclinado da la fuerza. Este cuida tu alcance'],
